// Create a min-heap of Huffman tree nodes
std::priority_queue<TreeNode*, std::vector<TreeNode*>, CompareNode> minHeap;

// First, create leaf nodes for each symbol and add to min-heap
for (int i = 0; i < size; i++) {
    TreeNode* leaf = new TreeNode();
    leaf->value = values[i];
    leaf->freq = freqs[i];
    leaf->left = leaf->right = nullptr;
    minHeap.push(leaf);
}

// Build the Huffman tree by combining nodes
while (minHeap.size() > 1) {
    // Extract two nodes with smallest frequency
    TreeNode* left = minHeap.top();
    minHeap.pop();
    TreeNode* right = minHeap.top();
    minHeap.pop();

    // Create a new internal node
    TreeNode* internal = new TreeNode();
    internal->value = -1;  // Using -1 to indicate internal node
    internal->freq = left->freq + right->freq;
    internal->left = left;
    internal->right = right;

    // Add the new node to the min-heap
    minHeap.push(internal);
}

// The remaining node is the root of the Huffman tree
TreeNode* root = minHeap.top();
minHeap.pop();

return root;

